// Verus specifications for the empty function
#[verifier::spec]
fn empty(n: u8) -> Vec<f64> {
    // Precondition: n must be less than or equal to 255 to fit in a Vec<u8>
    // This ensures that we do not attempt to create a vector larger than the maximum size.
    #[requires(n <= 255)]
    // Postcondition: The returned vector must have a length equal to n
    // and all elements must be initialized to 0.0.
    #[ensures(result.len() == n as usize)]
    #[ensures(result.iter().all(|&x| x == 0.0))]
    let mut result = Vec::with_capacity(n as usize);
    
    // Invariant: At the start of each iteration, the length of result is i and all elements are 0.0
    // where i is the current iteration index.
    // This invariant holds true for the loop.
    #[invariant(0 <= i && i <= n)]
    #[invariant(result.len() == i as usize)]
    #[invariant(result.iter().all(|&x| x == 0.0))]
    for i in 0..n {
        result.push(0.0);
    }
    
    result
}

